  function appliedVersions(db) {
    db.exec(
      `CREATE TABLE IF NOT EXISTS migrations (
       version    INTEGER PRIMARY KEY,
       name       TEXT NOT NULL,
       applied_at TEXT NOT NULL
     )`
    );
    const rows = db.prepare("SELECT version FROM migrations").all();
    return new Set(rows.map((row) => row.version));
  }
  function runMigrations(db) {
    const applied = appliedVersions(db);
    const pending = [...migrations].sort((a, b) => a.version - b.version).filter((migration) => !applied.has(migration.version));
    for (const migration of pending) {
      const apply3 = db.transaction(() => {
        migration.up(db);
        db.prepare(
          "INSERT INTO migrations (version, name, applied_at) VALUES (?, ?, ?)"
        ).run(migration.version, migration.name, (/* @__PURE__ */ new Date()).toISOString());
      });
      apply3();
      console.log(`[db] applied migration ${migration.version} (${migration.name})`);
    }
  }

