  function rowToAction(row) {
    return {
      id: row.id,
      courseId: row.course_id,
      turnId: row.turn_id,
      tool: row.tool,
      targetKind: row.target_kind,
      targetId: row.target_id,
      label: row.label,
      undoable: row.undoable === 1,
      undoneAt: row.undone_at,
      createdAt: row.created_at
    };
  }
  function createAgentJournal(db) {
    const insert = db.prepare(
      `INSERT INTO agent_actions
       (id, course_id, turn_id, tool, target_kind, target_id, label,
        undoable, undone_at, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL, ?)`
    );
    const selectForTurn = db.prepare(
      `SELECT * FROM agent_actions
     WHERE turn_id = ?
     ORDER BY created_at ASC, rowid ASC`
    );
    const selectUndoableForTurn = db.prepare(
      `SELECT * FROM agent_actions
     WHERE turn_id = ? AND undoable = 1 AND undone_at IS NULL
     ORDER BY created_at DESC, rowid DESC`
    );
    const markUndone = db.prepare(
      `UPDATE agent_actions
     SET undone_at = ?
     WHERE id = ? AND undone_at IS NULL`
    );
    return {
      record(entry2) {
        const action = {
          ...entry2,
          id: randomUUID(),
          undoneAt: null,
          createdAt: (/* @__PURE__ */ new Date()).toISOString()
        };
        insert.run(
          action.id,
          action.courseId,
          action.turnId,
          action.tool,
          action.targetKind,
          action.targetId,
          action.label,
          action.undoable ? 1 : 0,
          action.createdAt
        );
        return action;
      },
      forTurn(turnId) {
        const rows = selectForTurn.all(turnId);
        return { turnId, actions: rows.map(rowToAction) };
      },
      async undoTurn(turnId, undoers) {
        const rows = selectUndoableForTurn.all(turnId);
        let undone = 0;
        const results = [];
        for (const row of rows) {
          const action = rowToAction(row);
          try {
            const undo = undoers[action.targetKind];
            if (undo === void 0) {
              throw new Error(`no undo handler registered for ${action.targetKind}`);
            }
            await undo({
              courseId: action.courseId,
              targetId: action.targetId
            });
            const result = markUndone.run((/* @__PURE__ */ new Date()).toISOString(), action.id);
            if (result.changes !== 1) {
              throw new Error(`action "${action.id}" was not marked undone`);
            }
            undone += 1;
            results.push({ actionId: action.id, ok: true });
          } catch (error2) {
            results.push({
              actionId: action.id,
              ok: false,
              error: error2 instanceof Error ? error2.message : String(error2)
            });
          }
        }
        const failures = results.filter((result) => !result.ok);
        if (failures.length > 0) {
          console.error(
            `[agentTools] ${failures.length} action(s) failed to undo for turn "${turnId}"`,
            failures
          );
        }
        return { undone, results };
      }
    };
  }

